public static String appx(String word1, String word2) {
    Objects.requireNonNull(word1, "word1 cannot be null");
    Objects.requireNonNull(word2, "word2 cannot be null");

    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    int word1Length = word1.length();
    int word2Length = word2.length();
    int gcd = greatestCommonDenominator(word1Length, word2Length);
    int numerator = commonLetters * gcd;
    int denominator = word1Length * word2Length;

    return String.format("appx(%s, %s) = %d/%d", word1, word2, numerator, denominator);
}

private static int greatestCommonDenominator(int a, int b) {
    if (b == 0) {
        return a;
    }
    return greatestCommonDenominator(b, a % b);
}

