public int search(int[] nums, int target) {
    int low = 0, high = nums.length - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[low] <= nums[mid]) {
            if (nums[low] <= target && target < nums[mid]) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        } else {
            if (nums[mid] < target && target <= nums[high]) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Remove the smallest 5% of elements
    int min = (int) (arr.length * 0.05);
    int[] subArr = Arrays.copyOfRange(arr, min, arr.length - min);

    // Remove the largest 5% of elements
    int max = (int) (subArr.length * 0.05);
    int[] subSubArr = Arrays.copyOfRange(subArr, max, subArr.length - max);

    // Calculate the mean of the remaining elements
    double mean = subSubArr.stream().mapToDouble(i -> i).average().getAsDouble();

    return mean;
}

