public int minInsertions(String s) {
    // Initialize the variables to keep track of the minimum number of insertions and the current balance of the string
    int minInsertions = 0;
    int balance = 0;

    // Iterate over the string and update the balance and minimum number of insertions accordingly
    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else {
            balance--;
        }

        // If the balance becomes negative, we need to insert a '(' to make it balanced
        if (balance < 0) {
            minInsertions++;
            balance = 0;
        }
    }

    // If the balance is not zero at the end of the string, we need to insert more '(' to make it balanced
    if (balance != 0) {
        minInsertions += balance;
    }

    // Return the minimum number of insertions required to make the string balanced
    return minInsertions;
}

