public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    left[0] = 0;
    right[n - 1] = n;

    // Compute the left edge of each rectangle
    for (int i = 1; i < n; i++) {
        left[i] = i;
        while (left[i] > 0 && heights[left[i] - 1] >= heights[i]) {
            left[i] = left[left[i] - 1];
        }
    }

    // Compute the right edge of each rectangle
    for (int i = n - 2; i >= 0; i--) {
        right[i] = n - 1;
        while (right[i] < n - 1 && heights[right[i] + 1] >= heights[i]) {
            right[i] = right[right[i] + 1];
        }
    }

    // Compute the area of each rectangle
    int maxArea = 0;
    for (int i = 1; i < n - 1; i++) {
        maxArea = Math.max(maxArea, (right[i] - left[i] + 1) * heights[i]);
    }

    return maxArea;
}

